def txt(rows): return ' '.join(rows)

def main():
    old = json.load(open(JSON))
    rerun = 'v12' in (old.get('new_snippet') or '')                              # idempotent: the v11 WORDS block is kept as old_snippet
    old_words_v11 = old['old_snippet'] if rerun else old.get('new_snippet')
    older = list(old.get('older_snippets') or [])
    if not rerun and old.get('old_snippet') and old['old_snippet'] not in older: older.append(old['old_snippet'])
    words = []
    for b, rows, hold, e, face, cite, vb, src in W:
        w = {'beat': b, 'text': txt(rows), 'rows': rows, 'hold': hold, 'face': face, 'source': src}
        if e: w['emphasis'] = True
        if cite: w['cite'] = cite
        if vb: w['verbatim'] = True
        words.append(w)
    reading = ' / '.join(txt(r) for _, r, *_ in W)
    d = dict(old)
    d.update(words=words, reading=reading,
      thesis=("Thank you, monopoly. Profit comes from workers; machines replace them; the rate of profit falls; so the big capitals merge (Marx) and competition becomes monopoly (Lenin). "
              "Monopoly is a search function in capital that births AI through financialization of technology (CL175); finance bets, the startups run at a loss. "
              "AI replaces all labor, so the workers row and the rate go to zero: things are produced only so long as they can be produced with a profit (Marx), and production stops: post-economics. "
              "Then the freeze, which is of the superstructure: politics upgrades paranoia and tries to get a grip (Land); the dictatorship of finance takes up AI as a surveillance state, every citizen on file, to freeze the laws and the ruling ideas and hold its seat above the crisis (ours, from the client's reading, Dimitrov and Haz). "
              "It cannot hold: just when the elites think they are the most powerful they are the least powerful (Haz); post-economics runs away, into a race with China, and the crisis comes home (ours, from the client and Land); meltdown rips through the last dreams of top-down prediction and control (Land). "
              "The opening is ours, as a class: the AI that watched people now plans production; not a prediction, a plan (against Land); AI-driven national economic planning (Program); nationalized; everything in one hand. "
              "Sincerely, the working class."),
      hook="Frame 0: THANK YOU, / MONOPOLY. in one frame, in the split-flap board's own big cream flaps (MONOPOLY. in red), settled; sub impact on frame 0, the gasp at b0.5. It returns on the closing fist at b133; the last frames settle back onto the hook board (loop seam, the closing lockup dissolves into frame 0).",
      chant="(1) ALL IN. x3 on the pour (recorded gang shout, rising a step). (2) MELT. / DOWN. once each (high / low). (3) Lead EVERYTHING (yell + horn on F), crowd IN ONE HAND. (stadium burst), once.",
      clip_line="THE RATE OF PROFIT FALLS. / REPLACING ALL LABOR WITH AI over the ledger; THE AI THAT WATCHED PEOPLE / NOW PLANS PRODUCTION. / NOT A PREDICTION. A PLAN.",
      old_snippet=old_words_v11,
      new_snippet="const WORDS = [ /* v12: generated from this JSON into web/scenes/meltdown8_words.js (build_words.py) */ ]",
      older_snippets=older,
      notes=("v12 (cycle 8, critic's brief videos/review/meltdown_c8/NOTES.md; client 29 Sep: profits fall to zero, not costs; the fist restored after the hand is introduced; 'freeze the prices' was his hallucination, the real line is the surveillance state freezing the superstructure). "
             "58 s (lockup b142 + 1.4 s, 150 BPM). Restored: v1's profit-from-workers chain (now on the ledger's rows), SINCERELY, THE WORKING CLASS. (v8), NOT A PREDICTION. A PLAN. (v1), the worker's hand and the fist (v7/v8, now the anatomical hand built for v9), THE PARASITE/RULING IDEAS thread (as the superstructure freeze), Lenin/Marx/Haz/Land/Program in their own words with credits. Cut: COSTS NOTHING., NOTHING TO SELL., FREEZE THE PRICES., NOBODY'S BUYING., AI BREAKS OUT., HERE IT COMES., RIGHT ON TIME., ALREADY PLANNED., BET THE HOUSE., BURNS CASH., LAST ONE STANDING. (stock idiom or the wrong mechanism). Numbers are in-world texture (WORKERS, MACHINES, PROFIT % are illustrative, never a chart). "
             "29 Sep (client: 'Paraphrase it'; 'I am guidance, not ruler'): b74-b99 and b106-b117 rewritten in the piece's own voice from a synthesis of the client's 29 Sep reading, Haz (RESPONSE TO CRITICS; POSTMAGA on the CCRU; Wang Xiao), Land's Meltdown (runaway, the arms race, the crisis re-endogenized, the last dreams of prediction and control), Dimitrov, Lenin L7, Engels E3-E4 and the ML planners (Kantorovich, Glushkov, Lange). No client sentence is quoted. Land's 'last dreams' line now follows MELTDOWN. as a credited fragment (RIPS THROUGH ...), so it reads as the meltdown ending the surveillance state's control, and is answered by THE AI THAT WATCHED PEOPLE / NOW PLANS PRODUCTION. / NOT A PREDICTION. A PLAN."))
    json.dump(d, open(JSON, 'w'), indent=1, ensure_ascii=False)
    lines = ['// GENERATED by build_words.py from research/scripts_final/meltdown.json (do not edit): [beat, rows, hold, emphasis, face, cite]',
             'export const WORDS = [']
    for b, rows, hold, e, face, cite, vb, src in W:
        lines.append(f"  [{b}, {json.dumps(rows)}, {hold}, {e}, {json.dumps(face)}, {json.dumps(cite)}],")
    lines += ['];', 'export const CLOSE_B = 142;', '']
    open(JS, 'w').write('\n'.join(lines))
    print('ok', len(W), 'words')

if __name__ == '__main__':
    main()
